        159: ['stained_hardened_clay','white_terracotta'], 160: ['stained_glass_pane','white_stained_glass_pane'],
        171: ['carpet','white_carpet'], 251: ['concrete','white_concrete'], 252: ['concrete_powder','white_concrete_powder'],
