        white:-986896, orange:-425955, magenta:-3715395, light_blue:-12930086,
        yellow:-75715, lime:-8337633, pink:-816214, gray:-12103854,
        light_gray:-6447721, cyan:-15295332, purple:-7785800, blue:-12827478,
