        if (bareId === 'sign' || bareId.endsWith('_sign')) return 'Sign';
        if (bareId === 'banner' || bareId.endsWith('_banner')) return 'Banner';
        if (bareId === 'bed' || bareId.endsWith('_bed')) return 'Bed';
