        const data = ({SAVE:1, LOAD:2, CORNER:3, DATA:4})[mode] ?? 1;
        const mirrorCode = mirror === 'FRONT_BACK' ? 1 : mirror === 'LEFT_RIGHT' ? 2 : 0;
        const rotationCode = rotation === 'CLOCKWISE_90' ? 1 : rotation === 'CLOCKWISE_180' ? 2 : rotation === 'COUNTERCLOCKWISE_90' ? 3 : 0;
        const bedrockMirror = mirrorCode === 1 ? 'X' : mirrorCode === 2 ? 'Z' : 'NONE';
        let x = 0, z = 0;
        if (rotationCode === 1) {
            if (bedrockMirror === 'NONE') x -= sizeZ - 1;
            else if (bedrockMirror === 'X') { z -= sizeX - 1; x -= sizeZ - 1; }
        } else if (rotationCode === 2) {
            if (bedrockMirror === 'NONE') { x -= sizeX - 1; z -= sizeZ - 1; }
            else if (bedrockMirror === 'Z') x -= sizeX - 1;
            else if (bedrockMirror === 'X') z -= sizeZ - 1;
        } else if (rotationCode === 3) {
            if (bedrockMirror === 'NONE') z -= sizeX - 1;
            else if (bedrockMirror === 'Z') { z -= sizeX - 1; x -= sizeZ - 1; }
        } else {
            if (bedrockMirror === 'Z') z -= sizeZ - 1;
            else if (bedrockMirror === 'X') x -= sizeX - 1;
        }
