    function readStudioPreferences() {
        if (typeof localStorage === 'undefined') return {};
        try {
            const value = JSON.parse(localStorage.getItem(PREFERENCES_STORAGE_KEY) || '{}');
            return value && typeof value === 'object' && !Array.isArray(value) ? value : {};
        } catch {
            return {};
        }
    }

    function writeStudioPreferences(patch = {}) {
        if (typeof localStorage === 'undefined') return {};
        const next = {...readStudioPreferences(), ...(patch || {})};
        try { localStorage.setItem(PREFERENCES_STORAGE_KEY, JSON.stringify(next)); } catch {}
        return next;
    }

    function rememberedResourcePackPath() {
        const value = readStudioPreferences().resourcePackPath;
        try{const library=getStructurePackLibrary(false);if(library?.hasDefaults()){const ids=library.defaults();return ids.length?library.compose(ids):'';}}catch{}
        return typeof value==='string'?value.trim():'';
    }

    function rememberResourcePackPath(value) {
        const path = typeof value === 'string' ? value.trim() : '';
        writeStudioPreferences({resourcePackPath: path});
        return path;
    }

    function normalizeStructureBrushDescriptor(value = {}, fallbackBlock = 'minecraft:stone') {
        const rawBlock = typeof value === 'string' ? value : value?.block;
        const blockText = String(rawBlock || fallbackBlock || 'minecraft:stone').trim() || 'minecraft:stone';
        const block = blockText.includes(':') ? blockText : `minecraft:${blockText}`;
        let statesJson = '{}';
        if (typeof value?.statesJson === 'string') {
            try {
                const parsed = JSON.parse(value.statesJson || '{}');
                statesJson = JSON.stringify(parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed : {});
            } catch {}
        } else if (value?.states && typeof value.states === 'object' && !Array.isArray(value.states)) {
            try { statesJson = JSON.stringify(value.states); } catch {}
        }
        const versionNumber = Number(value?.version);
        return {
            block,
            statesJson,
            version: Number.isInteger(versionNumber) && versionNumber > 0 ? versionNumber : null,
            layer: Number(value?.layer) === 1 ? 1 : 0,
            ...(value?.exactPermutation === true ? {exactPermutation: true} : {}),
            ...(value?.empty === true ? {empty:true} : {}),
        };
    }

    function ensureStructureHotbarState() {
        if (structureHotbarSlots.length === STRUCTURE_HOTBAR_SIZE) return structureHotbarSlots;
        const preferences = readStudioPreferences();
        const stored = Array.isArray(preferences.hotbar) ? preferences.hotbar : [];
        const isLegacyPreset = stored.length===STRUCTURE_HOTBAR_SIZE && stored.every((value,index)=>{
            const slot=normalizeStructureBrushDescriptor(value,DEFAULT_STRUCTURE_HOTBAR[index]);
            return slot.block===DEFAULT_STRUCTURE_HOTBAR[index] && slot.statesJson==='{}' && slot.layer===0;
        });
        const saved = isLegacyPreset ? [] : stored;
        structureHotbarSlots = Array.from({length: STRUCTURE_HOTBAR_SIZE}, (_, index) => (
            normalizeStructureBrushDescriptor(saved[index] || (index===0 ? 'minecraft:stone' : {block:'minecraft:air',empty:true}), DEFAULT_STRUCTURE_HOTBAR[index])
        ));
        const savedSlot = Math.round(Number(preferences.activeHotbarSlot));
        structureActiveHotbarSlot = Number.isInteger(savedSlot)
            ? Math.max(0, Math.min(STRUCTURE_HOTBAR_SIZE - 1, savedSlot))
            : 0;
        return structureHotbarSlots;
    }

    function persistStructureHotbarState() {
        ensureStructureHotbarState();
        writeStudioPreferences({
            hotbar: structureHotbarSlots.map(slot => ({...slot})),
            activeHotbarSlot: structureActiveHotbarSlot,
        });
    }

    function structureHotbarPlacementPreference() {
        const saved = readStudioPreferences().hotbarPlacement;
        const mode = ['bottom', 'free', 'left', 'right'].includes(saved?.mode) ? saved.mode : 'bottom';
        return {
            mode,
            x: Number.isFinite(Number(saved?.x)) ? Number(saved.x) : null,
            y: Number.isFinite(Number(saved?.y)) ? Number(saved.y) : null,
            namePosition: saved?.namePosition === 'below' ? 'below' : 'above',
        };
    }

    function persistStructureHotbarPlacement(placement) {
        const normalized = {
            mode: ['bottom', 'free', 'left', 'right'].includes(placement?.mode) ? placement.mode : 'bottom',
            x: Number.isFinite(Number(placement?.x)) ? Math.round(Number(placement.x)) : null,
            y: Number.isFinite(Number(placement?.y)) ? Math.round(Number(placement.y)) : null,
            namePosition: placement?.namePosition === 'below' ? 'below' : 'above',
        };
        writeStudioPreferences({hotbarPlacement: normalized});
        return normalized;
    }

    function activeStructureBrushDescriptor() {
        ensureStructureHotbarState();
        const selected = structureHotbarSlots[structureActiveHotbarSlot] || normalizeStructureBrushDescriptor();
        return {
            ...selected,
            version: selected.version || Number(Project?.mcstructure_default_version) || 18168865,
        };
    }

    function structureBlockDisplayName(identifier) {
        const label = blockDictionary?.resolve(identifier)?.inventory?.name;
        if (typeof label === 'string' && label) return label;
        const value = String(identifier || '').replace(/^minecraft:/, '');
        if (!value) return tr('bedrock_structure.ui.unknown_block', 'Unknown block');
        if (TERRAIN_VANILLA_BLOCK_NAMES[identifier]) return TERRAIN_VANILLA_BLOCK_NAMES[identifier];
        return value.split('_').map(word => word ? word[0].toUpperCase() + word.slice(1) : '').join(' ');
    }

