        const [r, g, b] = solidColor ? [solidColor.r,solidColor.g,solidColor.b].map(value=>Math.round(value*255)) : blockPreviewColor(blockName);
        const ctx = page.ctx;
        ctx.clearRect(x - padding, y - padding, reserved, reserved);
