            ctx.fillRect(x, y, tile, tile);
            ctx.fillStyle = `rgba(${Math.max(0, r-28)},${Math.max(0, g-28)},${Math.max(0, b-28)},${mode === 'blend' ? 0.42 : 0.55})`;
            for (let py = 0; py < tile; py += 4) for (let px = (py / 4) % 2 ? 2 : 0; px < tile; px += 4) ctx.fillRect(x + px, y + py, 2, 2);
