        ctx.drawImage(page.canvas, x, y, 1, tile, x - padding, y, padding, tile);
        ctx.drawImage(page.canvas, x + tile - 1, y, 1, tile, x + tile, y, padding, tile);
        ctx.drawImage(page.canvas, x, y, tile, 1, x, y - padding, tile, padding);
        ctx.drawImage(page.canvas, x, y + tile - 1, tile, 1, x, y + tile, tile, padding);
        page.map.needsUpdate = true;
        const uvRect = [
            x / generatedStructureAtlas.size,
            1 - (y + tile) / generatedStructureAtlas.size,
            (x + tile) / generatedStructureAtlas.size,
            1 - y / generatedStructureAtlas.size,
        ];
        const descriptor = {key: `generated-atlas:${mode}`, material: page.material, uvRect, mode, atlasPage: `generated:${mode}`};
        generatedStructureAtlas.entries.set(key, descriptor);
