    function focusStructureCoordinate(position, layer = null) {
        const runtime = ensureLogicalRuntime();
        if (!runtime) return null;
        const normalized = position.slice(0, 3).map(value => Math.round(Number(value) || 0));
        let record = null;
        const layerOrder = layer === 0 || layer === 1 ? [Number(layer)] : [0, 1];
        for (const candidateLayer of layerOrder) {
            record = runtime.byKey.get(spatialRecordKey(normalized[0], normalized[1], normalized[2], candidateLayer));
            if (record) break;
        }
        if (!record) return null;
        setLogicalSelection([record]);
        try {
            const preview = window.Preview?.selected;
            const target = preview?.controls?.target;
            if (target?.set) {
                const focusPoint = typeof THREE !== 'undefined'
                    ? new THREE.Vector3(
                        (normalized[0] + 0.5) * BLOCK_SIZE,
                        (normalized[1] + 0.5) * BLOCK_SIZE,
                        (normalized[2] + 0.5) * BLOCK_SIZE
                    )
                    : null;
                const coordinateSpace = optimizedPreview?.root;
                if (focusPoint && coordinateSpace?.localToWorld) {
                    coordinateSpace.updateWorldMatrix?.(true, false);
                    coordinateSpace.localToWorld(focusPoint);
                }
                target.set(
                    focusPoint?.x ?? (normalized[0] + 0.5) * BLOCK_SIZE,
                    focusPoint?.y ?? (normalized[1] + 0.5) * BLOCK_SIZE,
                    focusPoint?.z ?? (normalized[2] + 0.5) * BLOCK_SIZE
                );
                preview.controls.update?.();
                preview.render?.();
            }
        } catch (error) {
            warnOnce('focus structure coordinate', error);
        }
        return record;
    }

