                        key: atlas.page.key,
                        material: atlas.page.material,
                        texture,
                        tint,
                        path: variant.path,
                        alias,
                        mode,
                        uvQuarterTurns: 0,
                        uvRect: atlas.uvRect,
                        atlasPage: atlas.page.id,
